// Code Pro — Fetch Sitemap XML (All Items)
// Purpose: discover + fetch raw sitemap XML for each website.
// Same contract as SuperCode "Fetch Sitemap XML": website, sourceUrl, rawXml, found.
// No expand / ranking — leave that to a downstream node.
//
// Mode: Run Once for All Items
// Options → Timeout: 0 (unlimited) so slow hosts do not soft-timeout
//
// utils.sitemap.fromWebsites:
//   - robots.txt (all Sitemap: lines) + common paths
//   - parallel candidate probes
//   - gzip .xml.gz
//   - attempts[] diagnostics when found:false

const sites = $input.all().map((i) => {
  const j = i.json || i;
  return j.Website || j.website || null;
});

const results = await utils.sitemap.fromWebsites(sites, {
  expand: false,           // discovery only — keep rawXml for downstream parse/rank
  includeRawXml: true,     // explicit: return the fetched XML body
  websiteConcurrency: 3,   // sites in parallel
  concurrency: 4,          // candidate URLs per site
  timeoutMs: 8000,         // per HTTP request (not the whole node)
});

return results.map((r, index) => ({
  json: {
    // Core contract (matches hand-rolled SuperCode script)
    website: r.website || null,
    sourceUrl: r.sourceUrl,
    rawXml: r.rawXml,
    found: r.found,
    // Diagnostics / extras (optional for downstream)
    kind: r.kind,
    base: r.base,
    robotsSitemaps: r.robotsSitemaps,
    attempts: r.found ? undefined : r.attempts,
    error: r.website
      ? r.found
        ? undefined
        : 'No sitemap XML found (see attempts)'
      : 'No website field on input item',
  },
  pairedItem: { item: index },
}));
